import re, math
def parse_value(text):
    m = re.fullmatch(r"\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*([A-Za-z]+)\s*", text)
    scales = {"s":1,"ns":1e-9,"ps":1e-12,"F":1,"fF":1e-15,"A":1,"uA":1e-6,"nA":1e-9,"V":1}
    if not m or m[2] not in scales: raise ValueError("Invalid measurement")
    value = float(m[1]) * scales[m[2]]
    if not math.isfinite(value): raise ValueError("Non-finite measurement")
    return value

labs.tests:
import math
assert math.isclose(parse_value(" 80 ps "),80e-12)
assert math.isclose(parse_value("-2.5e1 uA"),-25e-6)
assert parse_value(".8 V") == .8
for bad in ["FAILED", "NaN ps", "2 apples", "1e999 V", "5 ps extra"]:
    try: parse_value(bad)
    except ValueError: pass
    else: raise AssertionError("Must reject: " + bad)
print("PASS: normal values, signs, exponents and invalid measurements")

