def slacks(T, skew, cq_max, d_max, setup, u_setup, cq_min, d_min, hold, u_hold):
    return (T + skew - cq_max - d_max - setup - u_setup,
            cq_min + d_min - skew - hold - u_hold)

import math
def delay(r, cint, cload, scale=1):
    if r <= 0 or scale <= 0 or cint < 0 or cload < 0: raise ValueError("Invalid parameters")
    return math.log(2) * r / scale * (cint * scale + cload)

def crossing(times, volts, threshold, edge="rise", occurrence=1):
    if len(times)!=len(volts) or len(times)<2 or edge not in ("rise","fall") or occurrence<1: raise ValueError("Invalid request")
    if any(b<=a for a,b in zip(times,times[1:])): raise ValueError("Time must increase")
    count=0
    for t0,t1,v0,v1 in zip(times,times[1:],volts,volts[1:]):
        hit = v0<threshold<=v1 if edge=="rise" else v0>threshold>=v1
        if hit:
            count+=1
            if count==occurrence: return t0+(threshold-v0)*(t1-t0)/(v1-v0)
    raise ValueError("Crossing not found")

labs.tests:
assert crossing([0,1,2,3,4],[0,1,0,1,0],.5)==.5
assert crossing([0,1,2,3,4],[0,1,0,1,0],.5,"rise",2)==2.5
assert crossing([0,1,2],[0,1,0],.5,"fall")==1.5
for args in [([0,1],[0,0],.5),([1,0],[0,1],.5),([0,1],[0],.5)]:
    try: crossing(*args)
    except ValueError: pass
    else: raise AssertionError("Expected failure")
print("PASS: rising, falling, repeated edges and missing measurements")

