def rom_pass(c, time, leak, keeper, on, opposing, max_droop, min_swing):
    if c<=0 or time<0: raise ValueError("Invalid C or time")
    droop=max(leak-keeper,0)*time/c
    swing=max(on-keeper-opposing,0)*time/c
    return droop<=max_droop, swing>=min_swing

def interpolate(xs, ys, values, x, y):
    if len(xs)!=2 or len(ys)!=2 or xs[1]<=xs[0] or ys[1]<=ys[0]: raise ValueError("Invalid axes")
    if not(xs[0]<=x<=xs[1] and ys[0]<=y<=ys[1]): raise ValueError("Outside table")
    a=(x-xs[0])/(xs[1]-xs[0]); b=(y-ys[0])/(ys[1]-ys[0])
    return (1-a)*(1-b)*values[0][0]+(1-a)*b*values[0][1]+a*(1-b)*values[1][0]+a*b*values[1][1]

labs.tests:
assert interpolate([10,30],[2,6],[[20,40],[30,54]],15,5)==38.25
assert interpolate([10,30],[2,6],[[20,40],[30,54]],10,2)==20
try: interpolate([10,30],[2,6],[[20,40],[30,54]],5,5)
except ValueError: pass
else: raise AssertionError("Reject extrapolation")
print("PASS: axis orientation, exact corner and out-of-range query")

