from itertools import product
def manifest(cells, corners, slews, loads):
    return sorted(set(product(cells,corners,slews,loads)))

import math
from collections import Counter
def audit(expected, records):
    expected=set(expected); counts=Counter(r["key"] for r in records)
    invalid=set()
    for r in records:
        try: valid=math.isfinite(float(r["value"]))
        except (ValueError,TypeError): valid=False
        if not valid: invalid.add(r["key"])
    return {"missing":sorted(expected-set(counts)),"extra":sorted(set(counts)-expected),
            "duplicate":sorted(k for k,n in counts.items() if n>1),"invalid":sorted(invalid)}

labs.tests:
r=audit(["a","b","c"],[{"key":"a","value":4},{"key":"a","value":4},{"key":"b","value":"FAILED"},{"key":"x","value":float("nan")}])
assert r=={"missing":["c"],"extra":["x"],"duplicate":["a"],"invalid":["b","x"]}
assert audit([],[])=={"missing":[],"extra":[],"duplicate":[],"invalid":[]}
print("PASS: independent checks for coverage and numerical validity")

