import math
def bit_budget(bits, yield_target):
    if not isinstance(bits,int) or bits<=0 or not(0<yield_target<=1): raise ValueError("Invalid array")
    return -math.expm1(math.log(yield_target)/bits)

def butterfly(a,b,w,q):
    if q<=1: raise ValueError("Invalid modulus")
    t=(b*w)%q
    return (a+t)%q,(a-t)%q

import math
def regressions(baseline,current):
    for mapping in (baseline,current):
        if any(not math.isfinite(v) or v<0 for v in mapping.values()): raise ValueError("Invalid delay")
    return sorted(((k,current[k]-baseline[k]) for k in baseline.keys()&current.keys()),key=lambda x:(-x[1],x[0]))

labs.tests:
assert regressions({"a":20,"b":40,"c":10},{"a":25,"b":39,"x":6})==[("a",5),("b",-1)]
assert regressions({"z":1,"a":1},{"z":3,"a":3})==[("a",2),("z",2)]
try: regressions({"a":float("nan")},{"a":3})
except ValueError: pass
else: raise AssertionError("Invalid baseline must fail")
print("PASS: delta sign, matched cases, tie order and invalid evidence")

